use crate::{camera::Projection, editor::{Action, Change, Editor}, mesh::Mesh};
use session_rust::{Point, Vector};
use std::rc::Rc;

#[test]
fn fit_frames_the_selection_without_editing_its_mesh_or_history() {
    for mode in [Projection::Perspective, Projection::Orthographic] {
        let mut editor = Editor::default();
        editor.apply(Action::AddBox).unwrap();
        editor.apply(Action::Isometric).unwrap();
        editor.apply(Action::Projection(mode)).unwrap();
        editor.apply(Action::Fit).unwrap();
        let all_distance = editor.camera.distance;
        for _ in 0..3 { editor.apply(Action::SelectNext).unwrap(); }
        let id = editor.selected.unwrap();
        let mesh = Rc::clone(&editor.scene.objects()[2].mesh);
        let vertices = mesh.vertices().to_vec();
        let direction = editor.camera.orientation.rotate_vector(Vector::y_axis());
        assert_eq!(editor.apply(Action::Fit).unwrap(), Change::View);
        let selected = editor.scene.bounds_for(Some(id)).unwrap();
        assert_eq!(editor.camera.target, selected.centre());
        assert!(editor.camera.distance < all_distance);
        assert_eq!(editor.selected, Some(id));
        assert_eq!(editor.camera.projection, mode);
        let after = editor.camera.orientation.rotate_vector(Vector::y_axis());
        for i in 0..3 { assert!((direction[i] - after[i]).abs() < 1.0e-12); }
        for v in &vertices {
            let screen = editor.camera.view_projection().transform_point(&Point::new(v[0] as f64, v[1] as f64, v[2] as f64));
            assert!(screen[0].abs() < 0.95 && screen[1].abs() < 0.95);
            assert!((0.0..1.0).contains(&screen[2]));
        }
        assert!(Rc::ptr_eq(&mesh, &editor.scene.objects()[2].mesh));
        assert_eq!(mesh.vertices(), vertices);
        let fitted = editor.camera.uniform();
        editor.apply(Action::Fit).unwrap();
        assert_eq!(editor.camera.uniform(), fitted);
        editor.apply(Action::Undo).unwrap();
        assert!(!editor.scene.contains(id));
        assert!(editor.selected.is_none());
        assert_eq!(editor.camera.uniform(), fitted);
        editor.apply(Action::Redo).unwrap();
        assert!(editor.scene.contains(id));
        assert!(Rc::ptr_eq(&mesh, &editor.scene.objects()[2].mesh));
    }
}

#[test]
fn an_empty_or_stale_selection_falls_back_to_the_whole_scene() {
    let mut editor = Editor::default();
    let id = editor.scene.objects()[0].id;
    editor.scene.remove(id);
    editor.selected = Some(id);
    assert!(editor.scene.bounds_for(Some(id)).is_none());
    editor.apply(Action::Fit).unwrap();
    assert_eq!(editor.camera.target, editor.scene.bounds().unwrap().centre());
    let expected = editor.camera.uniform();
    editor.selected = None;
    editor.apply(Action::Fit).unwrap();
    assert_eq!(editor.camera.uniform(), expected);
}

#[test]
fn fitting_a_near_selection_keeps_distant_visible_geometry_pickable() {
    for mode in [Projection::Perspective, Projection::Orthographic] {
        let mut editor = Editor::default();
        editor.camera.projection = mode;
        editor.selected = Some(editor.scene.objects()[0].id);
        let distant = Mesh::new(vec![
            [-10.0, -10.0, -20.0, 0.2, 0.8, 0.3],
            [ 10.0, -10.0, -20.0, 0.2, 0.8, 0.3],
            [  0.0,  10.0, -20.0, 0.2, 0.8, 0.3],
        ], vec![0, 1, 2]).unwrap();
        let id = editor.scene.insert(distant).unwrap();
        editor.apply(Action::Fit).unwrap();
        assert!(editor.camera.extent > 20.0);
        let point = Point::new(-0.1, -0.6, -20.0);
        let screen = editor.camera.view_projection().transform_point(&point);
        assert!((0.0..1.0).contains(&screen[2]));
        // Remove the nearer surfaces without changing the camera: the distant one remains reachable.
        let near: Vec<_> = editor.scene.objects().iter().filter(|object| object.id != id).map(|object| object.id).collect();
        for id in near { editor.scene.remove(id); }
        editor.apply(Action::Pick([screen[0] as f32, screen[1] as f32])).unwrap();
        assert_eq!(editor.selected, Some(id));
    }
}

#[test]
fn fitting_scaled_model_coordinates_preserves_screen_scale() {
    for mode in [Projection::Perspective, Projection::Orthographic] {
        let mut projected = Vec::new();
        for scale in [0.001_f32, 1.0, 10_000.0] {
            let mut editor = Editor::default();
            editor.camera.projection = mode;
            let id = editor.scene.insert(Mesh::new(vec![
                [0.0, 0.0, 0.0, 0.9, 0.25, 0.45],
                [scale, 0.0, 0.0, 0.9, 0.25, 0.45],
                [0.0, scale, 0.0, 0.9, 0.25, 0.45],
            ], vec![0, 1, 2]).unwrap()).unwrap();
            editor.selected = Some(id);
            editor.apply(Action::Fit).unwrap();
            let point = editor.camera.view_projection().transform_point(&Point::new(scale as f64, 0.0, 0.0));
            projected.push([point[0], point[1]]);
            assert_eq!(editor.scene.objects().last().unwrap().mesh.vertices()[1][0], scale);
        }
        for point in &projected[1..] {
            for i in 0..2 { assert!((point[i] - projected[0][i]).abs() < 1.0e-6); }
        }
    }
}

